/**
 * 현재 단원과 연계된 선수학습 경고 찾기
 */
/**
 * 단원명이 충분히 유사한지 판별 (너무 짧은 부분 문자열 매칭 방지)
 * - 매칭 대상이 2글자 이하면 정확히 일치하거나 "~의", "~와" 등 조사가 붙은 경우만 허용
 * - 3글자 이상이면 부분 문자열 매칭 허용
 */
function isTopicMatch(topic: string, target: string): boolean {
  const tLower = topic.toLowerCase().trim();
  const gLower = target.toLowerCase().trim();

  // 정확히 일치
  if (tLower === gLower) return true;

  // 짧은 대상(2글자 이하, 예: "실수")은 단어 경계 매칭
  if (gLower.length <= 2) {
    // "실수의 대소 관계"에서 "실수" 매칭: "실수"로 시작하고 뒤에 조사/공백이 오는 경우
    const idx = tLower.indexOf(gLower);
    if (idx === -1) return false;
    // 시작 위치이거나 앞이 공백인 경우만
    if (idx !== 0 && tLower[idx - 1] !== ' ') return false;
    // 뒤에 아무것도 없거나 조사("의", "와", "과", "에", " ")가 오는 경우
    const afterIdx = idx + gLower.length;
    if (afterIdx >= tLower.length) return true;
    const nextChar = tLower[afterIdx];
    return ['의', '와', '과', '에', ' ', '·', ',', '('].includes(nextChar);
  }

  // 3글자 이상이면 보수적 매칭: 키워드 뒤에 확장 조사("의", "와", "과" 등)가 오면 다른 단원으로 간주
  // 예: "이차함수" ≠ "이차함수의 활용" (다른 단원)
  const idx = tLower.indexOf(gLower);
  if (idx === -1) return false;

  // 키워드 뒤에 아무것도 없으면 매칭
  const afterIdx = idx + gLower.length;
  if (afterIdx >= tLower.length) return true;

  // 키워드 뒤 문자 확인
  const nextChar = tLower[afterIdx];

  // 구분자(공백, >, ·, ,, ()가 오면 매칭 허용 (예: "이차함수 > 최대최소")
  if ([' ', '>', '·', ',', '(', ')'].includes(nextChar)) return true;

  // "의", "와", "과", "를", "을" 등 확장 조사가 오면 다른 단원으로 간주하여 매칭 안함
  // 예: "이차함수의 활용" vs "이차함수" → 매칭 안함
  return false;
}

export function findGradeConnections(topic: string, currentGrade?: string): GradeConnection[] {
  if (!topic) return [];

  const connections: GradeConnection[] = [];

  for (const conn of GRADE_CONNECTIONS) {
    // 현재 배우는 단원(toTopics)에서 매칭
    const isRelatedTopic = conn.toTopics.some(t => isTopicMatch(topic, t));

    // 선수학습 단원(fromTopic)에서 매칭
    const isPrerequisite = isTopicMatch(topic, conn.fromTopic);

    if (isRelatedTopic || isPrerequisite) {
      // 학년 필터 (현재 학년보다 낮은 선수학습만)
      if (currentGrade) {
        const gradeOrder: Record<string, number> = {
          '중1': 1, '중2': 2, '중3': 3,
          '고1': 4, '고2': 5, '고3': 6
        };
        const current = gradeOrder[currentGrade.slice(0, 2)] || 0;
        const from = gradeOrder[conn.fromGrade] || 0;
        if (from < current || isPrerequisite) {
          connections.push(conn);
        }
      } else {
        connections.push(conn);
      }
    }
  }

  return connections;
}

